// Iterate until a zeroed entry; cap iteration to avoid excessive work.
for (int i = 0; i < 32; ++i) {
    const ZMusicConfigurationSetting& e = cfg[i];
    if (!e.name && e.identifier == 0 && e.type == 0 && e.defaultVal == 0.0f && !e.defaultString) {
