ZMusic_MidiSource h = (ZMusic_MidiSource)midi_src;
// Choose device type in [-1,8] to match EMidiDevice range including default.
int devtype = (int)(*FUZZ_PARAM(unsigned int) % 10) - 1; // -1..8
// Optional device argument.
std::string devargS = FUZZ_PARAM_STR();
const char* devarg = devargS.c_str();
// Output filename must be writable; the runtime provides a valid temp file path.
const char* outname = FUZZ_PARAM_FILENAME();
// Subsong and samplerate; samplerate must be positive.
