// Build an aligned buffer of 32-bit words to satisfy the uint32_t* parameter.
std::string raw = FUZZ_PARAM_STR();
// Choose a byte size to provide to the detector; allow zero per API.
int maxBytes = (int)raw.size();
int size = (maxBytes == 0) ? 0 : (int)(*FUZZ_PARAM(unsigned int) % (unsigned)(maxBytes + 1));
// Ensure the pointer is 32-bit aligned: use a vector<uint32_t> with enough words to cover 'size'.
int words = (size + 3) / 4; // round up to cover 'size' bytes
if (words == 0) {
    // size == 0: pass a dummy aligned pointer; the callee must not read it.
    uint32_t dummy = 0;
    EMIDIType t = ZMusic_IdentifyMIDIType(&dummy, 0);
    (void)t;
} else {
    std::vector<uint32_t> aligned(words, 0);
    // Copy up to 'size' bytes from raw into the aligned storage.
    if (maxBytes > 0) {
        int toCopy = size;
        if (toCopy > maxBytes) toCopy = maxBytes;
        memcpy(aligned.data(), raw.data(), (size_t)toCopy);
    }
    EMIDIType t = ZMusic_IdentifyMIDIType(aligned.data(), size);
    (void)t;
}
// The buffer is not owned by the callee; no further action.

